Lemma stage2 :
  PECSS.iss_ctor_c_spec L HI ->
  forall (fx : FPState) R M model cr s K,
    PECH.H1 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R M model cr s -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1 cr1 s2 sm,
        PECH.H2 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R1 M1 model1 cr1 s s2 sm ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x34a10 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x34a00 M model) K.
Proof.
